/**
 * 中考专题 ⑤「现代文阅读」——卷面第三大题（文学类文本 + 实用类／非连续性文本）。
 *
 * 数据性质说明：
 * - **只做考情归纳**：`trends` 逐年写「考查形态 / 分值区间 / 选材倾向」，
 *   不复刻任何一年的真题原文、材料、题干与选项（真题有版权，学生需要的也是形态而非某一道题）。
 * - 题目**全部原创**。文学类训练用的是**本文件自撰的短篇**（见下方 `TEXT_A`—`TEXT_D` 与
 *   `SEG_1`—`SEG_4`，四篇各 700—830 字，另配四个百余字的技法小语段；取材于乡土、亲情、手艺、动物、成长，
 *   贴近中考选材）；
 *   实用类训练用的是**公开政策文件的表述 + 公开的常识性数据表述 + 情境化的自拟调查数据**
 *   （见 `MAT_P1`—`MAT_P7`）。凡属情境化调查的数字都写在「某市／某校」的调查里，
 *   是题目情境，不是对现实数据的陈述；涉及政策与常识的部分均可核查。
 * - 文学类文本用模板字符串常量而不是逐题复述材料：同一篇文本由 6—7 道题分角度设问
 *   （内容理解、概括、赏析、形象、作用、情感、写法），题干里引用同一常量，保证每题都能独立作答。
 * - `drills[].name` 同时是题目上的标签：分组训练走
 *   `/practice/zh-topics/zht-xiandai?tag=文学类·概括内容`，因此组名必须与题目 tags 的第一项完全一致。
 * - **逐类讲透（`sections`）**：本专题在 **14 个章节**（文学类 7 节 + 实用类 7 节）下各配
 *   `intro`（怎么判断）＋ `rules`（判定要点）＋ `examples`（正误对照，含 fix）＋ `pitfalls`，
 *   并有**同名训练分组**，学生「看完一节就刷这一节」。
 *   章节名 = `drills[].name` = 题目 `tags[0]`，三者严格一一对应，不留孤立分组。
 * - 原先的两个粗分组「实用类·说明文精读」「实用类·议论文精读」已**按考点并入实用类各章节**：
 *   说明对象、说明方法及其作用、说明语言的准确性（含「几乎」「大致」这类限定词）→「实用类·信息辨析」；
 *   说明对象特征的概括、议论文中心论点的概括 →「实用类·材料概括」；
 *   论据辨析、论证方法、论证思路（「提出观点—分析论证—得出结论」）→「实用类·跨材料整合」；
 *   议论文内容理解 →「实用类·信息辨析」。这样 14 节既覆盖七个实用类考点，也不丢掉单篇说明文与议论文的读法。
 *
 * 攻破标准：本专题的**每一道题都曾答对**（见 `lib/progress.ts` 的全题过关策略），
 * 所以每道题都必须讲得清、经得起追问。
 */

import type { ChineseExamTopic } from '../../../types';

/* ------------------------------------------------------------------ */
/* 原创训练文本（文学类）                                                */
/* ------------------------------------------------------------------ */

/** 文本 A：手艺与亲情（写人记事，约 760 字）。用于内容理解、概括、叠词赏析、形象、结尾作用、启示、写法。 */
const TEXT_A =
  '我家的老木柜是父亲打的，柜门上没有一颗钉子。\n'
  + '那年我八岁，蹲在院子里看他干活。父亲把一块木板立起来，眯起左眼，顺着木纹的方向看过去，像在端详一个熟人的脸。'
  + '他不用尺子量，只用铅笔在木头上轻轻划线，线细得像一根头发。锯子拉起来沙沙地响，木屑落在他的鞋面上，堆成薄薄一层，他也不抖。\n'
  + '「木头是有脾气的。」父亲说，「顺着它，它就听你的；拧着它，它就裂给你看。」\n'
  + '他凿榫眼的时候最安静。凿子一下一下往下走，木屑一小卷一小卷地冒出来，卷着，像一个个不肯散开的小问号。'
  + '他很少说话，只在每一次落锤之前把凿子扶正，再用掌心轻轻按一按，像是在跟那块木头商量。\n'
  + '柜子做好那天，我伸手去推柜门，门轴转得很轻，几乎没有声音。我问父亲为什么不用钉子，他蹲下来，把柜门卸下，'
  + '指着里面说：「钉子会锈，锈了就松；榫卯不一样，木头越干，它咬得越紧。」\n'
  + '后来我去外地读书，那只柜子还在老屋的墙角立着。南方的梅雨天一来，屋里的墙皮都起了泡，柜门却仍旧合得严丝合缝。'
  + '有一年冬天我回家，看见父亲戴着老花镜，正拿着小木锤，轻轻敲打柜门边的接缝。他说，天太干了，木头缩了，得让它重新咬紧。\n'
  + '他抬头看我，笑了一下：「东西跟人一样，松了就紧一紧，别急着换。」\n'
  + '如今父亲的手有些抖了，锯子挂在墙上，锈迹爬上了锯条。我打开那只柜门，里面还留着淡淡的木香——那是很多年前，'
  + '一个夏天的午后，父亲凿下的第一刀留下的。';

/** 文本 B：乡土与亲情（写人记事，约 830 字）。用于内容理解、时序概括、叠词赏析、形象、标题作用、情感、伏笔照应。 */
const TEXT_B =
  '外婆家院墙外有一棵枇杷树，比我年纪还大。\n'
  + '每年五月底，枇杷就黄了。黄得不急，先是最低处的几颗，青里透出一点淡黄，像小孩第一次笑时露出的一点牙；'
  + '过上四五天，中间那一层也跟上来了；最后才轮到树顶，那儿的果子被太阳晒得最久，黄得最浓，也最甜。\n'
  + '外婆有一根长长的竹钩，头上弯成一个小钩子。她站在树下，仰着头，竹钩一伸一收，枇杷就一颗一颗落进她挎着的竹篮里，'
  + '轻得像落了一阵黄雨。树顶的那些她从来够不着，也从来不勉强。「留给雀儿。」她说，「它们比我起得早。」\n'
  + '我小时候贪吃，常常等不到洗净就往嘴里塞，把嘴角弄得黄黄的。外婆看见不骂，只递过一块手巾，说：「慢些，果子不跑。」\n'
  + '我上初中后住校，一年只能回去两三趟。有一年五月，我打电话说想吃枇杷，外婆在电话那头停了一下，说：「树今年结得少，我给你留着。」\n'
  + '等我回到家，桌上果然摆着一小碗枇杷，个个饱满，连颜色都匀净，显然是挑过的。我剥开一颗，忽然发现碗底压着一张旧报纸，'
  + '报纸上的日期是一个月前。\n'
  + '我问外婆：「怎么放这么久？」她坐在竹椅上，摇着蒲扇，慢悠悠地说：「挑出来的，放阴凉处，能存。你要是再晚几天回来，我就只能自己吃了。」\n'
  + '她笑得眼睛都眯起来，像那棵树顶上的枇杷，黄得发亮。那一年，我第一次发现，外婆的白头发比枇杷花开得还满。\n'
  + '如今外婆不在了，枇杷树还年年黄。树顶的那些果子，始终没有谁来摘。风一过，就落进草里，发出很轻的一声。'
  + '我有时站在树下想：有些甜，是专门留着给别人的，留的人自己未必尝得到。';

/** 文本 C：动物与生态（写人记事，约 700 字）。用于内容理解、事迹概括、比喻赏析、形象辨析、以声收尾、对比与侧写。 */
const TEXT_C =
  '冬天，保护区的水面结了一层薄冰。巡护员老周把船撑进芦苇荡的时候，天还没亮透。\n'
  + '丹顶鹤站在浅水里，一只脚收进羽毛里，另一只脚踩在冰碴上，一动不动，像一根插在灰白水面上的红笔尖。'
  + '老周熄了马达，任船慢慢漂过去——他不敢靠得太近，也不敢弄出太响的动静。鹤听见水声，偏了偏头，没有飞。\n'
  + '「它认得我。」老周后来对我说。他在这片滩涂上守了十九年，认得每一巢鹤，也认得每一片被风压弯的芦苇。\n'
  + '十几年前，这里还不是这样。老周说，那时候有人下网捕鱼，也有人捡鹤蛋。有一年春天，一片滩涂上一窝蛋只剩下碎的壳。'
  + '从那以后，他和几个伙伴每天天不亮就来，冬天喂食，春天看巢，夏天守水。每年补种芦苇，一年一年补，滩涂才慢慢绿回来。\n'
  + '「为什么不把它们围起来，看得更牢？」我问。\n'
  + '老周摇头：「围起来，它就成家禽了。」\n'
  + '这几年，越冬的鹤群从几十只涨到了两百多只。年底统计的时候，技术员在纸上画下一串数字，老周站在旁边看，什么也没说，'
  + '只是把冻僵的手在袖口里搓了搓。\n'
  + '日头出来的时候，鹤抖了抖翅膀，走上岸，慢吞吞地啄食。老周蹲下来，抓了一把玉米撒在冰面上。玉米粒滚了一地，'
  + '鹤低头啄食，脖颈弯成一道柔和的弧。\n'
  + '船往回走时，芦苇丛里忽然起了一阵响动——那是风吹过成千上万片叶子的声音，像有人在水边悄悄翻着一本书。'
  + '老周关了马达，坐在船头，听。';

/** 文本 D：劳动与成长（写人记事，约 780 字）。用于内容理解、经过概括、词语与句式赏析、形象、情感启示、标题与结尾。 */
const TEXT_D =
  '七月的晒谷场是一个被太阳烤透的圆。\n'
  + '稻子收下来，摊在场上，用木耙推成一道道浅浅的沟。爷爷说，这样翻着晒，谷子才干得匀。他戴着草帽，光着的脚背上'
  + '有一层薄薄的黑，是多年晒出来的颜色。他弯腰的时候，稻谷的气息就从他的衣袖里散出来，又干又香。\n'
  + '中午是最难熬的时候。柏油一样烫的地面，隔着鞋底都能感觉到热度。风是吝啬的，偶尔来一阵，只掀动谷堆最上面的一层，'
  + '掀起一小片金色的浪，立刻又平了。\n'
  + '我坐在场边的草垛里，捧着一本翻了角的书。爷爷走过来，往我身边的谷堆上插了一顶草帽，说：「看书也得躲着点太阳。」'
  + '他说话的声音很低，像怕吵醒什么。\n'
  + '傍晚，天边开始堆云。爷爷抬头看了很久，忽然说：「收谷。」我还没反应过来，他已经把耙子推起来，谷子在耙齿下哗哗地响。'
  + '风越来越急，云也压得越来越低。邻居们也来了，一句话都不多说，各自找一件家伙，有的推，有的扫，有的装。'
  + '场上的人影在暮色里来回晃动，谁也没有停下来歇一歇。\n'
  + '雨点落下来的时候，最后一筐谷子刚进仓。爷爷靠在门框上喘气，草帽歪在脑后，脸上全是汗，可他笑得像个孩子：「抢回来了。」\n'
  + '那天夜里，雨一直下。我躺在竹床上听雨，忽然想起中午那一阵吝啬的风，和傍晚那一阵急切的风，原来它们都是庄稼人的时间表。'
  + '人要跟着风走，才不至于把一年收成丢在天上。\n'
  + '再长大一些，我离家读书。每逢下雨，我总会想起那个傍晚：场上的人一句话也不说，却把力气往同一个方向使。'
  + '那种默契，比任何口号都有力。';

/* ------------------------------------------------------------------ */
/* 原创训练语段（文学类·技法专项）                                       */
/* ------------------------------------------------------------------ */

/** 语段 1：写景状物，密集使用叠词。用于叠词赏析的集中训练。 */
const SEG_1 =
  '雪是夜里落的。天亮时推开院门，地上已经铺了厚厚的一层。檐下的冰凌一根一根垂着，亮晶晶的，风一吹，便轻轻碰在一起，'
  + '发出叮叮的细响。远处的屋顶都矮了下去，炊烟从雪白里慢慢升起来，淡淡的，像谁用铅笔轻轻画了一笔。';

/** 语段 2：连续动作，短句密集、节奏由急转缓。用于词语与句式赏析。 */
const SEG_2 =
  '他把书塞进书包，拉上拉链，抄起水杯，冲出门去。楼道里传来咚咚的脚步声，一级一级往下跳。到了楼下，他才发现鞋带松了，'
  + '便蹲下来系，系完，抬头看了一眼天——天很好，云很白，他忽然不想跑那么快了。';

/** 语段 3：情感前后反转的细节。用于情感变化与启示（开放题）。 */
const SEG_3 =
  '小时候，我嫌父亲身上的机油味难闻，他一进门，我就躲开。上高中住校，有一回深夜发烧，室友打不通我的电话，'
  + '辗转找到了父亲的号码。他赶到时已经凌晨两点，身上还是那股机油味。这一次，我却觉得那味道很安心——'
  + '那是他刚从修理厂出来，连衣服都没换。';

/** 语段 4：结尾补叙揭示真相。用于伏笔与照应的写法探究。 */
const SEG_4 =
  '母亲总在阳台的花盆里种薄荷。我问她为什么种这个，她说：「好活。」那年秋天我参加演讲比赛，上台前手心全是汗，'
  + '从口袋里摸出一小包薄荷叶——是出门前母亲塞给我的，用纸巾包着，还带着露水。后来我才知道，阳台上的那几盆薄荷，'
  + '是她知道我容易紧张以后才种的。';

/* ------------------------------------------------------------------ */
/* 原创训练材料（实用类／非连续性文本）                                  */
/* ------------------------------------------------------------------ */

/** 材料组 1：湿地修复与候鸟保护。 */
const MAT_P1 =
  '【材料一】湿地被称为「地球之肾」。它能蓄水调洪，也能净化水质：水流经过湿地时，泥沙和部分污染物会被水生植物与土壤拦下。\n'
  + '【材料二】某市在城郊修复了一片约两百公顷的滩涂湿地，补种芦苇、清理外来物种，并设置了观鸟栈道与限流围栏。'
  + '修复三年后，来这里停歇的水鸟种类由原来的三十余种增加到七十余种。\n'
  + '【材料三】有专家提醒，观鸟活动本身也可能带来干扰：人靠得太近、声音太响，都会惊扰鸟类；'
  + '因此在观鸟点设置安静区域、规定安全距离，比一味增加观鸟设施更重要。';

/** 材料组 2：传统技艺的传承与「手艺进校园」。 */
const MAT_P2 =
  '【材料一】某市非遗保护中心的统计显示，该市列入市级以上名录的传统技艺类项目有 40 余项，其中传承人年龄在 60 岁以上的超过七成。'
  + '部分项目因缺少年轻人接手，处于「人在艺在、人亡艺绝」的困境。\n'
  + '【材料二】近两年，该市多所中学把本地手艺请进课堂：木版水印、竹编、灰塑等被编成每周一节的实践活动课，由老艺人带徒授课。'
  + '一学期后，选课学生从最初的一个班扩大到六个班。\n'
  + '【材料三】有研究者指出，传统技艺进校园的关键不在「学会一门手艺」，而在让学生理解手艺背后的讲究——'
  + '选料为什么这样选、工序为什么不能颠倒。只有把「为什么」讲清楚，手艺才可能被真正传下去；否则学生记住的只是几个动作。';

/** 材料组 3：数字阅读与纸质阅读（含统计表）。 */
const MAT_P3 =
  '【材料一】有调查显示，近年来我国成年国民数字化阅读方式的接触率总体呈上升趋势，而人均纸质图书阅读量并未随之明显下降。\n'
  + '【材料二】某中学对本校 600 名学生的阅读方式做了调查，结果如下表：\n'
  + '　　阅读方式　　　　　　　　　人数\n'
  + '　　只用纸质书　　　　　　　　168\n'
  + '　　纸质书为主，偶尔看电子书　276\n'
  + '　　电子书为主，偶尔看纸质书　108\n'
  + '　　只用电子书　　　　　　　　48\n'
  + '【材料三】语文老师提醒：纸质阅读便于前后翻检、做批注，适合读需要反复琢磨的书；电子阅读便于检索、携带方便，'
  + '适合查资料和读篇幅短的文章。两种方式各有其用，关键是读什么书、用什么方式。';

/** 材料组 4：校园体育「每天一小时」。 */
const MAT_P4 =
  '【材料一】新修订的《中华人民共和国体育法》要求学校保障学生在校期间每天参加不少于一小时体育锻炼。'
  + '教育部等部门多次强调，要开齐开足体育课，不得随意挤占。\n'
  + '【材料二】某校 2025 年秋季学期统计：实行「每天一节体育课＋大课间」后，学生体质健康测试优良率由上学期的 41% 提高到 52%；'
  + '同期因身体不适请假的记录并未明显增加。\n'
  + '【材料三】有教师反映，个别班级仍存在「临近考试就占体育课」的情况。学校随后把体育课与大课间纳入课表督查：'
  + '占课需报备，并由年级统一安排调补。';

/** 材料组 5：快递包装的绿色转型（含统计表）。 */
